WITH cleaned AS (SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, DATEDIFF(start_date, end_date) / 7 AS weeks_end_date_to_start_date FROM subscriptions WHERE status IN ('EXPIRED', 'PAUSED')) SELECT c.country, e.plan, COUNT(*) AS cnt, SUM(e.weeks_end_date_to_start_date) AS total_weeks_end_date_to_start_date, GROUPING_ID() AS grouping_level FROM cleaned e INNER JOIN customers c ON e.customer_id = c.id GROUP BY ROLLUP (c.country, e.plan);
